/**
 * Unit tests for MultiplePiePlot.setPieChart.
 */
public class MultiplePiePlot_setPieChart_TriageGen2Test {

    private MultiplePiePlot multiplePiePlot;

    @Before
    public void setUp() {
        multiplePiePlot = new MultiplePiePlot();
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSetPieChart_NullArgument() {
        multiplePiePlot.setPieChart(null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSetPieChart_WrongPlotType() {
        // Create a chart that does not have a PiePlot (e.g., a BarChart or a simple JFreeChart with null plot)
        // Since JFreeChart is abstract/complex, we use a standard Chart that isn't a PieChart
        // We'll use a BarChart or similar if available, but here we can mock or use a known non-pie chart.
        // A common way is to create a chart with a different plot type.
        // For simplicity in this test environment, we'll use a chart that is not a PieChart.
        // Note: We'll assume a standard JFreeChart instance where we can control the plot.

        // Since we cannot easily instantiate a non-pie JFreeChart without dependencies, 
        // we'll use a mock or a standard chart type that is definitely not PiePlot.
        // Let's simulate a chart with a different plot type via a subclass or a known type.
        // In JFreeChart, a LineChart has a LineAndShapePlot.

        // However, the most direct way to trigger the 'instanceof' failure is to pass a chart
        // whose getPlot() returns something other than PiePlot.
        JFreeChart nonPieChart = new JFreeChart("Non-Pie Chart", null, null, false);
        // Note: If getPlot() returns null, it also fails the 'instanceof' check.

        multiplePiePlot.setPieChart(nonPieChart);
    }

    @Test
    public void testSetPieChart_Success() {
        // Create a valid PieChart
        DefaultPieDataset dataset = new DefaultPieDataset();
        dataset.setValue("A", 10.0);
        PieChart pieChart = new PieChart("Test Pie Chart", dataset);

        // Ensure it is indeed a PiePlot
        assertNotNull(pieChart.getPlot());
        org.junit.Assert.assertTrue(pieChart.getPlot() instanceof PiePlot);

        // Execute
        multiplePiePlot.setPieChart(pieChart);

        // Verify
        assertEquals(pieChart, multiplePiePlot.getPieChart());
    }
}
